import keyboardUtil from 'src/utils/keyboard';
const USED_KEYS = [
  'E',
  'G',
  'R',
  'S',
  'W',
  'K',
  'T',
  '+',
  'F',
  'ArrowDown',
  'ArrowRight',
];
export default {
  methods: {
    fixedShortCutKeyList() {
      const comb_key = keyboardUtil.methods.getCombinationKey();
      const used_keys_list = USED_KEYS;
      USED_KEYS.forEach(function (value, index) {
        used_keys_list[index] = comb_key.toUpperCase() + value.toUpperCase();
      });
      return used_keys_list;
    },

    keyDownEvent(e) {
      try {
        // logInfo('keyDownEvent Medi', e);
        // logInfo(this.groupShortCutMap);
        const combKey = keyboardUtil.methods.isCombinationKey(e);

        if (e.key === 'Tab') {
          this.TabKeyHandler(e);
          return;
        }

        if (e.key === 'Enter') {
          this.EnterKeyHandler(e);
          return;
        }

        // combKey + E
        if (e.keyCode === 69 && combKey === true) {
          e.preventDefault();
          this.clickExport();
          return;
        }

        // combKey + F
        if (e.keyCode === 70 && combKey === true) {
          e.preventDefault();
          this.focusFirstFieldOnGroup();
          return;
        }

        // combKey + G
        if (e.keyCode === 71 && combKey === true) {
          e.preventDefault();
          this.selectFieldFromNextGroup(e);
          return;
        }

        // combKey + R
        if (e.keyCode === 82 && combKey === true) {
          e.preventDefault();
          this.rejectDocument();
          return;
        }

        // combKey + S
        if (e.keyCode === 83 && combKey === true) {
          e.preventDefault();
          this.saveData();
          return;
        }

        // combKey + T
        if (e.keyCode === 84 && combKey === true) {
          this.jumpToTable(e);
          return;
        }

        // combKey + W
        if (e.keyCode === 87 && combKey === true) {
          e.preventDefault();
          this.exportWithSonderWunsch();
          return;
        }

        // combKey + Plus
        const enter_codes = keyboardUtil.methods.getAddRowKeyCodes();
        if (enter_codes.includes(e.keyCode) && combKey === true) {
          e.preventDefault();
          this.triggerTableAddRow(e);
          return;
        }

        //USER DEFINED
        if (e.keyCode) {
          this.focusOnGroupFromMap(e);
        }
      } catch (e) {
        logInfo(e);
      }
    },

    EnterKeyHandler(e) {
      e.preventDefault();
      const field_name = this.getFocusedFieldName();
      if (!field_name) {
        return;
      }
      const next_field = this.findNextField(field_name);
      if (!next_field) {
        return;
      }
      this.focusOnField(next_field, true, true);
    },

    TabKeyHandler(e) {
      e.preventDefault();
      const field_name = this.getFocusedFieldName();
      if (!field_name) {
        return;
      }

      this.validateAndSelectNextInvalidField(field_name);
    },

    getFocusedFieldName() {
      let field_name = '';
      const activeElement = this.getActiveElement();
      if (!activeElement) {
        return field_name;
      }

      field_name = this.getNameFromDataAttribute(activeElement);
      if (!field_name) {
        field_name = this.getNameFromChildTypeAttribute(activeElement);
      }

      return field_name;
    },

    getNameFromDataAttribute(activeElement) {
      let field_name = '';
      if (!activeElement.hasAttribute('data-name')) {
        return field_name;
      }
      field_name = activeElement.getAttribute('data-name');
      return field_name;
    },

    getNameFromChildTypeAttribute(activeElement) {
      let field_name = '';
      if (!activeElement.hasAttribute('child_type')) {
        return field_name;
      }

      field_name = activeElement.getAttribute('id');
      return field_name;
    },

    getActiveElement() {
      let focused_element =
        (document.hasFocus() &&
          document.activeElement !== document.body &&
          document.activeElement !== document.documentElement &&
          document.activeElement) ||
        null;

      return focused_element;
    },
  },
};
